         <entry name="KeyboardBrightness" type="Int">
             <default>50</default>
         </entry>
+        <entry name="TurnOffKeyboardBacklightWhenIdle" type="Bool">
+            <default>false</default>
+        </entry>
+        <entry name="TurnOffKeyboardBacklightIdleTimeoutSec" type="Int">
+            <default>10</default>
+        </entry>
     </group>

