@@ -94,12 +98,58 @@ bool KeyboardBrightnessControl::isSupported()

 bool KeyboardBrightnessControl::loadAction(const PowerDevil::ProfileSettings &profileSettings)
 {
-    if (!profileSettings.useProfileSpecificKeyboardBrightness()) {
-        return false;
+    m_defaultValue = profileSettings.useProfileSpecificKeyboardBrightness() ? profileSettings.keyboardBrightness() : -1;
+
+    if (profileSettings.turnOffKeyboardBacklightWhenIdle()) {
+        registerIdleTimeout(std::chrono::seconds(profileSettings.turnOffKeyboardBacklightIdleTimeoutSec()));
     }

-    m_defaultValue = profileSettings.keyboardBrightness();
-    return true;
+    return m_defaultValue >= 0 || profileSettings.turnOffKeyboardBacklightWhenIdle();
+}
+
+void KeyboardBrightnessControl::onProfileUnload()
+{
+    m_isOffForIdle = false;
+    updateBacklight();
+}
+
+void KeyboardBrightnessControl::onIdleTimeout(std::chrono::milliseconds /*timeout*/)
+{
+    m_isOffForIdle = true;
+    updateBacklight();
+}
+
+void KeyboardBrightnessControl::onWakeupFromIdle()
+{
+    m_isOffForIdle = false;
+    updateBacklight();
+}
+
+void KeyboardBrightnessControl::updateBacklight()
+{
+    const bool turnOff = m_isOffForIdle;
+    if (turnOff == m_isTurnedOff) {
+        return;
+    }
+
+    if (turnOff) {
+        // Leave it alone if it's already off, e.g. because the display was dimmed or the user turned it off
+        const int brightness = keyboardBrightness();
+        if (brightness <= 0) {
+            return;
+        }
+        qCDebug(POWERDEVIL) << "KeyboardBrightnessControl: turning off keyboard backlight";
+        m_brightnessBeforeTurningOff = brightness;
+        m_isTurnedOff = true;
+        core()->keyboardBrightnessController()->setBrightness(0);
+    } else {
+        m_isTurnedOff = false;
+        // Don't override a brightness that was set in the meantime
+        if (keyboardBrightness() == 0) {
+            qCDebug(POWERDEVIL) << "KeyboardBrightnessControl: restoring keyboard backlight to" << m_brightnessBeforeTurningOff;
+            core()->keyboardBrightnessController()->setBrightness(m_brightnessBeforeTurningOff);
+        }
+    }
 }

