From af8510320a4fbba330fa69ed71cb11e2fd916e60 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 16:13:06 +0100
Subject: [PATCH 2/2] daemon, kcm: optionally turn off keyboard backlight in
 bright light

When a light sensor is present, power profiles can now turn the keyboard
backlight off in a brightly lit room and bring it back once the light is
dim again, ignoring short changes like KWin's automatic brightness does.

BUG: 516629
---
 PowerDevilProfileSettings.kcfg                |   3 +
 .../bundled/keyboardbrightnesscontrol.cpp     | 160 +++++++++++++++++-
 .../bundled/keyboardbrightnesscontrol.h       |  16 ++
 kcm/PowerKCM.cpp                              |  28 +++
 kcm/PowerKCM.h                                |   5 +
 kcm/ui/ProfileConfig.qml                      |  13 ++
 6 files changed, 222 insertions(+), 3 deletions(-)

diff --git a/PowerDevilProfileSettings.kcfg b/PowerDevilProfileSettings.kcfg
index 44955b94c..314916c2d 100644
--- a/PowerDevilProfileSettings.kcfg
+++ b/PowerDevilProfileSettings.kcfg
@@ -34,6 +34,9 @@ SPDX-License-Identifier: CC0-1.0
         <entry name="TurnOffKeyboardBacklightIdleTimeoutSec" type="Int">
             <default>10</default>
         </entry>
+        <entry name="TurnOffKeyboardBacklightInBrightLight" type="Bool">
+            <default>false</default>
+        </entry>
     </group>

     <group name="Display" parentGroupName="$(ProfileId)">
diff --git a/daemon/actions/bundled/keyboardbrightnesscontrol.cpp b/daemon/actions/bundled/keyboardbrightnesscontrol.cpp
index 7e8f52744..5dcfe45b2 100644
--- a/daemon/actions/bundled/keyboardbrightnesscontrol.cpp
+++ b/daemon/actions/bundled/keyboardbrightnesscontrol.cpp
@@ -23,13 +23,32 @@
 #include <KLocalizedString>
 #include <KPluginFactory>

+#include <QDBusConnection>
+#include <QDBusConnectionInterface>
 #include <QDBusInterface>
 #include <QDBusPendingCall>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
