+#include <QTimer>

 K_PLUGIN_CLASS_WITH_JSON(PowerDevil::BundledActions::KeyboardBrightnessControl, "powerdevilkeyboardbrightnesscontrolaction.json")

 using namespace Qt::StringLiterals;

+static const QString SENSOR_PROXY_SERVICE = u"net.hadess.SensorProxy"_s;
+static const QString SENSOR_PROXY_PATH = u"/net/hadess/SensorProxy"_s;
+static const QString SENSOR_PROXY_INTERFACE = u"net.hadess.SensorProxy"_s;
+static const QString DBUS_PROPERTIES_INTERFACE = u"org.freedesktop.DBus.Properties"_s;
+
+// A room lit for reading or office work, or by daylight, is around 300-500 lux, and keys can be read without the
+// backlight there; a home in the evening is usually below 150 lux. The backlight goes off above the first level
+// and comes back below the second one, so that readings around a single threshold don't make it flicker.
+constexpr double BRIGHT_LIGHT_LUX = 300;
+constexpr double DIM_LIGHT_LUX = 150;
+// Like KWin's automatic screen brightness, ignore light changes that don't last, such as a passing shadow
+constexpr auto LIGHT_CHANGE_DELAY = std::chrono::seconds(2);
+
 namespace PowerDevil::BundledActions
 {
