+    m_lightChangeTimer = new QTimer(this);
+    m_lightChangeTimer->setSingleShot(true);
+    m_lightChangeTimer->setInterval(LIGHT_CHANGE_DELAY);
+    connect(m_lightChangeTimer, &QTimer::timeout, this, &KeyboardBrightnessControl::applyLightLevel);
+
+    auto sensorWatcher = new QDBusServiceWatcher(SENSOR_PROXY_SERVICE, QDBusConnection::systemBus(), QDBusServiceWatcher::WatchForOwnerChange, this);
+    connect(sensorWatcher, &QDBusServiceWatcher::serviceRegistered, this, [this] {
+        m_isLightSensorClaimed = false;
+        if (m_turnOffInBrightLight) {
+            claimLightSensor();
+        }
+    });
+    connect(sensorWatcher, &QDBusServiceWatcher::serviceUnregistered, this, [this] {
+        m_isLightSensorClaimed = false;
+        m_lightLevel.reset();
+        m_lightChangeTimer->stop();
+        m_isOffForBrightLight = false;
+        updateBacklight();
+    });
 }

